contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 val) public payable {
        uint256 beforeEther = address(c).balance;
        bool reverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 afterEther = address(c).balance;
        assert(!reverted && c.MinSum() == val && afterEther == beforeEther);
    }

    receive() external payable {}
}

