// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val) internal {
        uint256 beforeEther = address(c).balance;
        bool reverted;
        try c.SetMinSum(val) { reverted = false; } catch { reverted = true; }
        uint256 afterEther = address(c).balance;
        assertTrue(!reverted && c.MinSum() == val && afterEther == beforeEther);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
